const steps=[{message:'Halo Kak Nadia, mengingatkan sewa kamar A01 sebesar Rp1.250.000 ya. Setelah transfer, boleh kirim buktinya. Terima kasih 🙏',caption:'Ilustrasi alur · belum ada pesan yang dikirim.',button:'Lihat langkah berikutnya',badge:'Jatuh tempo besok',tone:'amber'},{message:'Bukti transfer diterima. Lampirkan pada tagihan Nadia untuk bulan yang sesuai, lalu periksa nominal dan mutasi rekening sebelum mengonfirmasi.',caption:'Ilustrasi alur · bukti diterima belum berarti dana terverifikasi.',button:'Lihat konfirmasi pembayaran',badge:'Perlu diperiksa',tone:'blue'},{message:'Dana sudah masuk dan pembayaran dikonfirmasi pengelola. Tagihan bulan ini ditandai lunas dan dikeluarkan dari antrean pengingat.',caption:'Ilustrasi alur · pembayaran ditandai lunas secara manual.',button:'Ulangi contoh alur',badge:'Lunas ✓',tone:'green'}];let step=0;function showStep(index){step=index;const data=steps[step];document.querySelector('#demo-message').textContent=data.message;document.querySelector('#demo-caption').textContent=data.caption;document.querySelector('#demo-button').innerHTML=data.button+' <span>→</span>';const badge=document.querySelector('.demo-person>.status');badge.textContent=data.badge;badge.className='status '+data.tone;document.querySelectorAll('[data-step]').forEach((button,i)=>{button.classList.toggle('selected',i===step);button.setAttribute('aria-pressed',String(i===step))})}document.querySelector('#demo-button').onclick=()=>showStep((step+1)%steps.length);document.querySelectorAll('[data-step]').forEach(button=>button.onclick=()=>showStep(Number(button.dataset.step)));showStep(0);
